INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (912070346204926147, 31093577, 'Luxury Hotel room in Amsterdam!', 'Relax in this unique and quiet accommodation. 25 minutes from the city center accessible by metro or bus or by bike.<br />2 minutes walk from the beaches to relax after a long day in the city. You are on the ideal address for your dream vacation in Amsterdam.', 'Gaasperdam - Driemond, Amsterdam', 45.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1062752844947604934, 31093577, 'Family stay in Amsterdam.', 'Make new memories in this unique, family-friendly accommodation. A very quiet place and close to the city center, 25 minutes by metro and direct. The beach is a 5-minute walk, everything for your comfort, ideal place with children or friends. <br />The best of ideal!', 'Gaasperdam - Driemond, Amsterdam', 123.67, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1116586866996363653, 568048648, 'Numa | Large 1 Bedroom Apartment with Sofa Bed', 'This comfortable apartment with one bedroom offers 50 sqm of space. Ideal for up to four people, its double bed (180x200), sofabed (160x200), and modern bathroom with shower make this stay a perfect way to experience Amsterdam. Theres also a kitchen and a dining table, so youll have everything you need for maximum comfort and minimal stress.', 'De Baarsjes - Oud-West, Amsterdam', 266.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1586962972552886160, 568048648, 'Numa | 1 Bedroom Apartment near Vondelpark', 'Ideal for up to two people, this comfortable apartment with one bedroom offers 34 sqm of space. Double bed (180x200) and modern bathroom with shower make this stay a perfect way to experience Amsterdam. <br />Theres also a sofa, a kitchen and a dining table, so youll have everything you need for maximum comfort and minimal stress.', 'De Baarsjes - Oud-West, Amsterdam', 323.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1068644385514194281, 556401137, 'Claudia M, room in family apartment', 'Hi, from time to time i rent 1 room (10 square menter) in in my apartment located in the ''Leidseplein'' area. <br />The museums are at walking distance and my house is located right next to the canals.<br />The bathroom is shared, there is no kitchen available and pets are not allowed.<br />Please note that i live in the apartment too with my family, so is very important that you are mindful and re', 'Centrum-Oost, Amsterdam', 87.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1074389223466445272, 556401137, 'Carla N, room in family apartment', 'Hi, from time to time i rent 1 room (10 square menter) in in my apartment located in the ''Leidseplein'' area. <br />The museums are at walking distance and my house is located right next to the canals.<br />The bathroom is shared, there is no kitchen available and pets are not allowed.<br />Please note that i live in the apartment too with my family, so is very important that you are mindful and re', 'Centrum-Oost, Amsterdam', 87.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1471627383721829735, 591582826, 'City Hotel Rembrandt Square - Deluxe Loft suite', 'Deluxe Suite with private bathroom.<br /><br />A perfect stay in a historic Amsterdam setting. This stylish suite combines modern comfort with the charm of a monumental building, featuring high ceilings, a spacious open-plan layout, and a luxurious lofted double bed. Relax in the comfortable sitting area and enjoy views of the citys vibrant atmosphere just outside your window. Ideal for couples, f', 'Centrum-Oost, Amsterdam', 464.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1471642920944694957, 591582826, 'City Hotel Rembrandt Square - Deluxe double room', 'Deluxe Twin/Double Room with private bathroom.<br /><br /> Enjoy comfort and contemporary design in the heart of Amsterdam. This stylish room features either a luxurious double bed or two separate twin beds - perfect for couples, friends, or colleagues traveling together.', 'Centrum-Oost, Amsterdam', 292.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1369443627129749321, 248652946, 'Beautiful Appartment in Adam Oud Zuid', 'This stunning mansion is situated in a villa on the prestigious Apollolaan, a location that offers both access to the city center and a route out of Amsterdam.<br /><br />The penthouse what we offer is on the ground floor, seperated from the entire mansion. It is designed in the Amsterdamse Stijl, blending vintage elements with modern eye-catchers.<br /><br />Within a 250-meter radius, youll find', 'Zuid, Amsterdam', 263.5, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1373049712518317700, 248652946, 'Double Floor Appartment in Rivierenbuurt', '<b>Guest access</b><br />We have keylock for our guests to check in<br /><br /><b>Registration Details</b><br />0363 4CDB 79A6 F2CF A972', 'De Pijp - Rivierenbuurt, Amsterdam', 288.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1145422775904303199, 218582446, 'Numa | Medium Studio with Kitchen', 'This comfortable studio offers 24 sqm of space. Ideal for up to two people, its double bed (160x200) and modern bathroom with shower make this stay a perfect way to experience Amsterdam. Theres also a kitchen and a dining table, so youll have everything you need for maximum comfort and minimal stress.', 'Centrum-Oost, Amsterdam', 252.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1145444486856229903, 218582446, 'Numa | Medium Duplex Studio with Kitchen', 'This comfortable studio offers 21 sqm of space. Ideal for up to three people, its double bed (160x200) , single bed (80x210) and modern bathroom with shower make this stay a perfect way to experience Amsterdam. Theres also a kitchen and a dining table, so youll have everything you need for maximum comfort and minimal stress.', 'Centrum-Oost, Amsterdam', 283.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (10512492, 54036035, 'Nieuw studio appartement met privebadkamer', 'Whole new studio apartment. On the Noordermarkt in the center of Amsterdam. It is a small studio with a new bathroom (private). There is no kitchen, but there is a refrigerator and the possibility to make coffee/tea. Bedding and towels are provided.', 'Centrum-West, Amsterdam', 134.5, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1052843680639684974, 54036035, 'Appartement met prive badkamer', 'From this centrally located apartment, everything is within walking distance in the city center of Amsterdam.', 'Centrum-West, Amsterdam', 140.5, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (40245488, 23609488, 'Romantic studio on houseboat in super location!!', 'Situated on one of the most beautiful canals of the canal belt in the historic centre of Amsterdam you will find this lovely houseboat. Imagine waking up to the gentle rocking and the sound of the waterbirds. If you are looking for a special stay, you will not find a better location to experience staying on a houseboat. The houseboat studio is very nice and the location is super. It is the ultimat', 'Centrum-West, Amsterdam', 248.5, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (52605292, 23609488, 'Galeforce One - Jordaan houseboat studio', 'Galeforce One is a charming houseboat studio with gorgeous canal views. <br /><br />It has a bedroom, private bathroom with walk-in shower, toilet and vanity with hairdryer.<br /><br />There is a fridge with a bottle of welcome wine to welcome you, a microwave, coffee machine and water kettle, coffee and tea is provided. <br /><br />Step onto the little terrace to watch boats drift by and feel lik', 'Centrum-West, Amsterdam', 248.5, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (4864384, 18482089, '2p Balcony Room - Quiet Street - Airport - Center', 'Well located room including sunny balcony in quiet neighbourhood. With boxspring suitable for two persons. Including two spacious wardrobes. (Shared) Bathroom next to the room.<br /><br />Location:<br />Excellent transport facilities to the center and Schiphol Airport.<br /><br />Parking:<br />* Paid Parking: Mo-Sa from 9.00 - 19.00<br />* On Sunday free parking<br />* Free parking on walking dist', 'De Aker - Nieuw Sloten, Amsterdam', 129.37, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (5012728, 18482089, 'Spacious room - quiet neighbourhood', 'Affordable room with two seperate beds. With lavabo. Fast Internet (glassfiber). (Shared) Kitchenette on same floor. (Shared) Bathroom and toilet on 2nd floor. <br /><br />Location:<br />Excellent transport facilities to the center and Schiphol Airport.<br /><br />Parking:<br />* Paid Parking: Mo-Sa from 9.00 - 19.00<br />* On Sunday free parking<br />* Free parking in village nearby (on walking d', 'De Aker - Nieuw Sloten, Amsterdam', 150.0, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1082713624856032256, 551883998, 'Homely studio close to main sights.', 'Bedroom with separate kitchenette and a private bathroom in a real Amsterdam souterrain. Naturally cool in the summer. iVery central location, in walking distance from Museum square and Dam square. Amidst nice restaurants and shops and public transport right on your doorstep this BnB will make your stay in Amsterdam very easy going.', 'De Baarsjes - Oud-West, Amsterdam', 123.5, 'Y');
INSERT INTO properties (property_id, host_id, title, description, location, price_per_night, is_available) VALUES (1450545400868731787, 551883998, 'Charming room close to major sights', 'Charming room with annex bathroom and pantry in a hip, lively street. The BnB is in walking distance to all major sights, nightlife and musea. It is situatated in an authentic Amsterdam souterrain and naturally cool in the summer.', 'De Baarsjes - Oud-West, Amsterdam', 99.0, 'Y');
